-- NEMIX PORTAL: qo‘shimcha sxema. Eski content/submissions jadvallariga tegmaydi.
-- Supabase SQL Editor'da bir marta to‘liq ishga tushiring.
create extension if not exists pgcrypto with schema extensions;
create table if not exists public.nemix_profiles(user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('admin','teacher')), full_name text, created_at timestamptz default now());
create table if not exists public.nemix_groups(id uuid primary key default gen_random_uuid(), name text not null, level text not null, teacher_id uuid references auth.users(id), created_at timestamptz default now());
create table if not exists public.nemix_students(id uuid primary key default gen_random_uuid(), full_name text not null, phone text, level text not null default 'A1', group_id uuid references public.nemix_groups(id) on delete set null, access_hash text not null unique, payment_status text not null default 'unpaid' check(payment_status in ('paid','unpaid','overdue')), active boolean not null default true, created_at timestamptz default now());
create table if not exists public.nemix_attendance(id uuid primary key default gen_random_uuid(), group_id uuid not null references public.nemix_groups(id) on delete cascade, student_id uuid not null references public.nemix_students(id) on delete cascade, attendance_date date not null, present boolean not null, absence_reason text, marked_by uuid references auth.users(id), created_at timestamptz default now(), unique(student_id,attendance_date));
create table if not exists public.nemix_questions(id uuid primary key default gen_random_uuid(), level text not null, question text not null, options jsonb not null, correct_index int not null check(correct_index between 0 and 3), active boolean not null default true, created_at timestamptz default now());
create table if not exists public.nemix_attempts(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.nemix_students(id) on delete cascade, attempt_date date not null default current_date, total int not null, correct int not null, earned int not null, created_at timestamptz default now(), unique(student_id,attempt_date));
create table if not exists public.nemix_rewards(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.nemix_students(id) on delete cascade, stars int not null, amount_uzs int not null default 10000, status text not null default 'pending' check(status in ('pending','approved','paid','rejected')), created_at timestamptz default now());

alter table public.nemix_profiles enable row level security;
alter table public.nemix_groups enable row level security;
alter table public.nemix_students enable row level security;
alter table public.nemix_attendance enable row level security;
alter table public.nemix_questions enable row level security;
alter table public.nemix_attempts enable row level security;
alter table public.nemix_rewards enable row level security;
-- Barcha jadvallarga bevosita brauzer CRUD ruxsati berilmaydi. Faqat tekshiruvchi RPC funksiyalar ishlaydi.
revoke all on public.nemix_profiles,public.nemix_groups,public.nemix_students,public.nemix_attendance,public.nemix_questions,public.nemix_attempts,public.nemix_rewards from anon,authenticated;
grant usage on schema public to anon,authenticated;

create or replace function public.nemix_is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from nemix_profiles where user_id=auth.uid() and role='admin') $$;
create or replace function public.nemix_is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from nemix_profiles where user_id=auth.uid() and role in ('admin','teacher')) $$;
create or replace function public.nemix_my_profile() returns jsonb language plpgsql security definer set search_path=public as $$ declare r jsonb; begin select to_jsonb(p) into r from nemix_profiles p where p.user_id=auth.uid(); if r is null then raise exception 'Xodim roli biriktirilmagan'; end if; return r; end $$;

create or replace function public.nemix_student_portal(p_token text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare s nemix_students; pts int; n int; begin select * into s from nemix_students where access_hash=encode(digest(p_token,'sha256'),'hex') and active=true; if s.id is null then return null; end if; select coalesce(sum(earned),0),count(*) into pts,n from nemix_attempts where student_id=s.id; return jsonb_build_object('profile',jsonb_build_object('id',s.id,'full_name',s.full_name,'level',s.level,'group_name',(select name from nemix_groups where id=s.group_id)),'points',pts,'tests_completed',n,'tests_to_bonus',greatest(0,300-n),'payment_status',s.payment_status,'bonus_status',(select status from nemix_rewards where student_id=s.id order by created_at desc limit 1)); end $$;
create or replace function public.nemix_daily_test(p_token text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare sid uuid; qs jsonb; begin select id into sid from nemix_students where access_hash=encode(digest(p_token,'sha256'),'hex') and active=true; if sid is null then raise exception 'Kirish kodi noto‘g‘ri'; end if; if exists(select 1 from nemix_attempts where student_id=sid and attempt_date=current_date) then raise exception 'Bugungi test allaqachon bajarilgan'; end if; select coalesce(jsonb_agg(jsonb_build_object('question',question,'options',options) order by md5(id::text || current_date::text || sid::text)),'[]'::jsonb) into qs from (select * from nemix_questions where active and level=(select level from nemix_students where id=sid) order by md5(id::text || current_date::text || sid::text) limit 10) q; return jsonb_build_object('questions',qs); end $$;
create or replace function public.nemix_submit_test(p_token text,p_answers jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare sid uuid; lvl text; q record; i int:=0; c int:=0; total int; earned int; begin select id,level into sid,lvl from nemix_students where access_hash=encode(digest(p_token,'sha256'),'hex') and active=true; if sid is null then raise exception 'Kirish kodi noto‘g‘ri'; end if; if exists(select 1 from nemix_attempts where student_id=sid and attempt_date=current_date) then raise exception 'Bugungi test allaqachon bajarilgan'; end if; for q in select correct_index from nemix_questions where active and level=lvl order by md5(id::text || current_date::text || sid::text) limit 10 loop i:=i+1; if (p_answers->>(i-1))::int=q.correct_index then c:=c+1; end if; end loop; total:=i; if total=0 then raise exception 'Bu daraja uchun test mavjud emas'; end if; earned:=c; insert into nemix_attempts(student_id,total,correct,earned) values(sid,total,c,earned); if (select count(*) from nemix_attempts where student_id=sid)>=300 and not exists(select 1 from nemix_rewards where student_id=sid and status in ('pending','approved','paid')) then insert into nemix_rewards(student_id,stars,amount_uzs) values(sid,300,10000); end if; return jsonb_build_object('total',total,'correct',c,'earned',earned); end $$;
create or replace function public.nemix_staff_dashboard() returns jsonb language plpgsql security definer set search_path=public as $$ declare g jsonb; s jsonb; begin if not nemix_is_staff() then raise exception 'Ruxsat yo‘q'; end if; select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'level',x.level,'student_count',(select count(*) from nemix_students st where st.group_id=x.id))),'[]'::jsonb) into g from nemix_groups x where nemix_is_admin() or x.teacher_id=auth.uid(); select coalesce(jsonb_agg(jsonb_build_object('id',st.id,'full_name',st.full_name,'phone',st.phone,'level',st.level,'group_id',st.group_id,'group_name',(select name from nemix_groups where id=st.group_id),'payment_status',st.payment_status)),'[]'::jsonb) into s from nemix_students st where nemix_is_admin() or st.group_id in(select id from nemix_groups where teacher_id=auth.uid()); if nemix_is_admin() then return jsonb_build_object('groups',g,'students',s,'attendance',(select coalesce(jsonb_agg(to_jsonb(a)),'[]'::jsonb) from nemix_attendance a)); end if; return jsonb_build_object('groups',g,'students',s); end $$;
create or replace function public.nemix_create_group(p_name text,p_level text) returns uuid language plpgsql security definer set search_path=public as $$ declare gid uuid; begin if not nemix_is_staff() then raise exception 'Faqat xodim guruh yaratadi'; end if; insert into nemix_groups(name,level,teacher_id) values(p_name,p_level,case when nemix_is_admin() then null else auth.uid() end) returning id into gid; return gid; end $$;
create or replace function public.nemix_create_student(p_full_name text,p_phone text,p_level text,p_group_id uuid,p_payment_status text,p_token text) returns uuid language plpgsql security definer set search_path=public,extensions as $$ declare sid uuid; begin if not nemix_is_admin() then raise exception 'Faqat admin o‘quvchi qo‘sha oladi'; end if; if p_group_id is not null and not exists(select 1 from nemix_groups where id=p_group_id) then raise exception 'Guruh topilmadi'; end if; insert into nemix_students(full_name,phone,level,group_id,payment_status,access_hash) values(p_full_name,p_phone,p_level,p_group_id,p_payment_status,encode(digest(p_token,'sha256'),'hex')) returning id into sid; return sid; end $$;
create or replace function public.nemix_save_attendance(p_group_id uuid,p_date date,p_items jsonb) returns int language plpgsql security definer set search_path=public as $$ declare x jsonb; n int:=0; begin if not nemix_is_staff() then raise exception 'Ruxsat yo‘q'; end if; if not nemix_is_admin() and not exists(select 1 from nemix_groups where id=p_group_id and teacher_id=auth.uid()) then raise exception 'Bu guruh sizga biriktirilmagan'; end if; for x in select * from jsonb_array_elements(p_items) loop if not exists(select 1 from nemix_students where id=(x->>'student_id')::uuid and group_id=p_group_id) then continue; end if; insert into nemix_attendance(group_id,student_id,attendance_date,present,absence_reason,marked_by) values(p_group_id,(x->>'student_id')::uuid,p_date,(x->>'present')::boolean,case when (x->>'present')::boolean then null else nullif(x->>'reason','') end,auth.uid()) on conflict(student_id,attendance_date) do update set present=excluded.present,absence_reason=excluded.absence_reason,marked_by=auth.uid(); n:=n+1; end loop; return n; end $$;
create or replace function public.nemix_add_question(p_level text,p_question text,p_options jsonb,p_answer int) returns uuid language plpgsql security definer set search_path=public as $$ declare qid uuid; begin if not nemix_is_admin() then raise exception 'Faqat admin test savoli qo‘sha oladi'; end if; insert into nemix_questions(level,question,options,correct_index) values(p_level,p_question,p_options,p_answer) returning id into qid; return qid; end $$;

