-- Admin UID: loyihada avval yaratilgan admin foydalanuvchi. Teacher profillarini admin qo‘lda qo‘shadi.
insert into public.nemix_profiles(user_id,role,full_name) values('292d6a05-d711-4b2b-8b4b-6db30c5f74ed','admin','Nemix Admin') on conflict(user_id) do update set role='admin';
revoke all on function nemix_student_portal(text),nemix_daily_test(text),nemix_submit_test(text,jsonb),nemix_my_profile(),nemix_staff_dashboard(),nemix_create_group(text,text),nemix_create_student(text,text,text,uuid,text,text),nemix_save_attendance(uuid,date,jsonb),nemix_add_question(text,text,jsonb,int) from public;
grant execute on function nemix_student_portal(text),nemix_daily_test(text),nemix_submit_test(text,jsonb) to anon,authenticated;
grant execute on function nemix_my_profile(),nemix_staff_dashboard(),nemix_create_group(text,text),nemix_create_student(text,text,text,uuid,text,text),nemix_save_attendance(uuid,date,jsonb),nemix_add_question(text,text,jsonb,int) to authenticated;
